  'terrible': [.95,.85,.02,.02,.02],
  'bad': [.85,.95,.02,.02,.02],
  'okay': [0.02,0.25,0.95,.65,.35],
  'good': [.02,.05,.55,.95,.93],
  'amazing': [.02,.02,.02,.65,0.95]
};
var qudPrior = function(){ categorical({vs:['quality','arousal'], ps:[1,1]}) };
var qudFns = { quality: function(state){return state.quality}, arousal: function(state){return state.arousal} };

var meaning = function(utterance, stateQuality) {
  return flip(literalSemantics[utterance][stateQuality - 1]);
};

var lambda = 1.25;
var valueFunction = function(s) { return lambda * s; };
var alpha = 10;

var literalListener = mem(function(utterance) {
  return Infer({method: 'enumerate'}, function() {
    var state = uniformDraw(fullStates);
    condition(meaning(utterance, state.quality));
    return state;
  });
});

var speaker1 = mem(function(state, qud, phi) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(utterances);
    var ll = literalListener(utt);
    var marginalizedLL = marginalize(ll, qud);
    var epistemic = marginalizedLL.score(qudFns[qud](state));
    var social = expectation(marginalizedLL, valueFunction);
    var speakerUtility = phi * epistemic + (1 - phi) * social;
    factor(alpha * speakerUtility);
    return utt;
  });
});

var pragmaticListener = function(utterance) {
  return Infer({method: 'enumerate'}, function() {
    var state = uniformDraw(fullStates);
    var qud = qudPrior();
    var phi = uniformDraw(_.range(0.05, 0.95, 0.05));
    observe(speaker1(state, qud, phi), utterance);
    return {state: state, qud: qud, phi: phi};
  });
};

var plOkay = pragmaticListener('okay');
var stateMarginal = marginalize(plOkay, 'state');
var qualityMarginal = marginalize(stateMarginal, 'quality');
var phiMarginal = marginalize(plOkay, 'phi');

var ANSWER = {
  expectedQuality: expectation(qualityMarginal),
